def _locations(records):
    return [f"{record['path']} id={record['cell_id']}" for record in records]

# %% ../nbs/10_graph.ipynb #3e7fe7f3
def _callee_locations(graph, symbol):
    return _locations(_definitions_for_symbol(graph, symbol))

