    blocks.append("<callees>")
    blocks.extend(f"<symbol>{xml_escape(symbol)}</symbol>" for symbol in self.callees())
    blocks.append("</callees>")
    return f"<symbol_graph {attrs}>\n" + "\n".join(blocks) + "\n</symbol_graph>"

