def _merge_symbol_nodes_by_name(state):
    for name, ids in _symbol_ids_by_name(state["nodes"]).items():
        bucket = state["symbol_nodes_by_name"].setdefault(name, [])
        for node_id in ids:
            if node_id not in bucket:
                bucket.append(node_id)

